    fun cue(a: Learn.Action): String = if (a.cue.startsWith("Stand for rakʿah ")) "رکعت ${a.rakah} کے لیے کھڑے ہوں۔" else cues.getValue(a.cue)
    fun position(step: Adhkar.Step): String {
        if (step.position == "Second prostration") return "دوسرا سجدہ"
        if (step.position.startsWith("Standing · rakʿah ")) return "قیام؛ رکعت ${step.position.substringAfterLast(' ')}"
        val index = Adhkar.salah.indexOfFirst { it.arabic == step.arabic }
        return stepPositions[index.coerceAtLeast(0)]
    }
